from pathlib import Path

p = Path('source/main.cpp')
s = p.read_text()

def rep(old, new, label, count=1):
    global s
    if old not in s:
        raise SystemExit(f'{label} not found')
    s = s.replace(old, new, count)

# Track the user's safer recovery choice without changing the active HOC value
# until they explicitly confirm it.
rep('''bool g_bootPrompt = false;\nbool g_scanForLowUv = false;''', '''bool g_bootPrompt = false;\nint g_bootRecoveryCandidate = -1;\nbool g_scanForLowUv = false;''', 'boot recovery candidate global')

# Generic built-in test pages: consistent Known PASS wording.
rep('''    uiPrintf(row + 2, "+ : Known PASS / Skip");''', '''    uiPrintf(row + 2, "+ : Known PASS / Skip step");''', 'footer known pass')

# Successful CPU voltage scan screen: crash guidance belongs directly to A,
# and every page that starts a test gets a Known PASS / Skip step option.
rep('''    uiPrintf(row++, "A : Start automatic stability test");\n    row++;\n    uiPrintf(row++, "If the test crashes, reboot and");\n    uiPrintf(row++, "open the Wizard again.");\n    uiPrintf(row++, "B : Exit");''', '''    uiPrintf(row++, "A : Start automatic stability test");\n    uiPrintf(row++, "    If the test crashes, reboot and");\n    uiPrintf(row++, "    open the Wizard again.");\n    uiPrintf(row++, "+ : Known PASS / Skip step");\n    uiPrintf(row++, "B : Exit");''', 'scan success test UI')

# Boot check: remove redundant success wording and simplify safer-recovery text.
rep('''    if (state == BootInference::RequestedActive) {\n        uiPrintf(row++, "\\x1b[32mRequested value is active.\\x1b[0m");\n        uiPrintf(row++, "Console booted with requested value.");\n        row++;\n        uiPrintf(row++, "Only continue if normal CFW booted AND:");''', '''    if (state == BootInference::RequestedActive) {\n        uiPrintf(row++, "Only continue if normal CFW booted AND:");''', 'boot requested-active cleanup')

rep('''    } else if (state == BootInference::SaferActive) {\n        uiPrintf(row++, "\\x1b[33mRequested value is NOT active.\\x1b[0m");\n        uiPrintf(row++, "It looks like this value did not boot.");\n        uiPrintf(row++, "Recovery restored last working value.");\n        row++;\n        if (g.stage == Stage::LowUvQuick)\n            uiPrintf(row++, "\\x1b[32mLast good value: Low UV %d\\x1b[0m", active);\n        else if (g.stage == Stage::LowVminQuick)\n            uiPrintf(row++, "\\x1b[32mLast good value: Low VMIN %d mV\\x1b[0m", active);\n        row++;\n        uiPrintf(row++, "Confirm this matches your recovery.");\n        uiPrintf(row++, "A : Confirm last good value");\n        uiPrintf(row++, "X : This is not correct");\n''', '''    } else if (state == BootInference::SaferActive) {\n        if (g_bootRecoveryCandidate < 0) g_bootRecoveryCandidate = active;\n        if (g.stage == Stage::LowUvQuick)\n            uiPrintf(row++, "It looks like Low UV %d did not boot.", g.lowUvTest);\n        else if (g.stage == Stage::LowVminQuick)\n            uiPrintf(row++, "It looks like Low VMIN %d mV did not boot.", g.lowVminTest);\n        row++;\n        if (g.stage == Stage::LowUvQuick)\n            uiPrintf(row++, "\\x1b[32mLast good value: Low UV %d\\x1b[0m", g_bootRecoveryCandidate);\n        else if (g.stage == Stage::LowVminQuick)\n            uiPrintf(row++, "\\x1b[32mLast good value: Low VMIN %d mV\\x1b[0m", g_bootRecoveryCandidate);\n        row++;\n        uiPrintf(row++, "A : Confirm last good value");\n        uiPrintf(row++, "X : Try one safer value");\n''', 'boot safer-active cleanup')

# Region-validation page: same test-start layout and skip option.
rep('''        uiPrintf(row++, "A : Start automatic stability test");\n        row++;\n        uiPrintf(row++, "If the test crashes, reboot and");\n        uiPrintf(row++, "open the Wizard again.");\n        uiPrintf(row++, "B : Exit");''', '''        uiPrintf(row++, "A : Start automatic stability test");\n        uiPrintf(row++, "    If the test crashes, reboot and");\n        uiPrintf(row++, "    open the Wizard again.");\n        uiPrintf(row++, "+ : Known PASS / Skip step");\n        uiPrintf(row++, "B : Exit");''', 'region validation test UI')

# Helper for an explicitly known-pass automatic CPU region test. This mirrors
# the successful completion path without running the stress test.
needle = '''void runAutomaticLowUvScan() {\n    runAutomaticVoltageScan(true);\n}\n\nvoid runAutomaticRegionValidation(bool forLowUv) {'''
insert = '''void runAutomaticLowUvScan() {\n    runAutomaticVoltageScan(true);\n}\n\nvoid skipAutomaticRegionValidation(bool forLowUv) {\n    clearVminSweepData();\n    if (forLowUv) {\n        if (g.lowVminGood <= LOW_VMIN_MIN_MV) {\n            g.stage = Stage::LowVminLong;\n            g.stageReadyAfterBoot = true;\n        } else {\n            g.stage = Stage::LowVminQuick;\n            g.lowVminTest = std::max(LOW_VMIN_MIN_MV, g.lowVminGood - LOW_VMIN_STEP_MV);\n            g.stageReadyAfterBoot = false;\n        }\n    } else {\n        if (g.vddqGood <= VDDQ_MIN_MV) {\n            g.stage = Stage::VddqLong;\n            g.stageReadyAfterBoot = true;\n        } else {\n            g.stage = Stage::VddqQuick;\n            g.vddqTest = g.vddqGood - VDDQ_STEP_MV;\n            g.stageReadyAfterBoot = false;\n        }\n    }\n    g.pendingConfigMask = Config_None;\n    saveState();\n}\n\nvoid runAutomaticRegionValidation(bool forLowUv) {'''
rep(needle, insert, 'skip region validation helper')

# Boot prompt input handling. On a recovery screen, X walks one additional
# step toward safety. A either accepts the currently active safe value, or if
# the user selected an even safer value, writes it automatically and requests
# the normal reboot flow before scanning/testing.
old_boot = '''        if (g_bootPrompt) {\n            if (k & HidNpadButton_A) {\n                int active = 0;\n                const BootInference state = inferBootState(&active);\n                if (state == BootInference::RequestedActive) {\n                    g.rebootPending = false;\n                    g_bootPrompt = false;\n                    g.pendingConfigMask = Config_None;\n                    if (g.stage == Stage::Preparation) {\n                        g.stage = Stage::LowUvQuick;\n                        g.lowUvTest = std::min(LOW_UV_MAX, g.lowUvGood + 1);\n                        g.stageReadyAfterBoot = false;\n                    } else if (g.stage == Stage::LowUvQuick || g.stage == Stage::LowVminQuick) {\n                        handlePass();\n                    } else {\n                        g.stageReadyAfterBoot = true;\n                        saveState();\n                    }\n                } else if (state == BootInference::SaferActive) {\n                    g.rebootPending = false;\n                    g_bootPrompt = false;\n                    g.pendingConfigMask = Config_None;\n                    if (g.stage == Stage::LowUvQuick) {\n                        g.lowUvGood = std::max(0, active);\n                        g.stage = Stage::LowUvLong;\n                        g.stageReadyAfterBoot = true;\n                    } else if (g.stage == Stage::LowVminQuick) {\n                        g.lowVminGood = active;\n                        g.stage = Stage::LowVminLong;\n                        g.stageReadyAfterBoot = true;\n                    }\n                    clearVminSweepData();\n                    saveState();\n                }\n                redraw = true;\n            } else if (k & HidNpadButton_X) {\n                g.rebootPending = false;\n                g_bootPrompt = false;\n                handleFail(true);\n                redraw = true;\n            } else if (k & HidNpadButton_B) {\n                break;\n            }\n            svcSleepThread(20'000'000);\n            continue;\n        }\n'''
new_boot = '''        if (g_bootPrompt) {\n            int active = 0;\n            const BootInference state = inferBootState(&active);\n            if (k & HidNpadButton_A) {\n                if (state == BootInference::RequestedActive) {\n                    g_bootRecoveryCandidate = -1;\n                    g.rebootPending = false;\n                    g_bootPrompt = false;\n                    g.pendingConfigMask = Config_None;\n                    if (g.stage == Stage::Preparation) {\n                        g.stage = Stage::LowUvQuick;\n                        g.lowUvTest = std::min(LOW_UV_MAX, g.lowUvGood + 1);\n                        g.stageReadyAfterBoot = false;\n                    } else if (g.stage == Stage::LowUvQuick || g.stage == Stage::LowVminQuick) {\n                        handlePass();\n                    } else {\n                        g.stageReadyAfterBoot = true;\n                        saveState();\n                    }\n                } else if (state == BootInference::SaferActive) {\n                    const int confirmed = g_bootRecoveryCandidate >= 0 ? g_bootRecoveryCandidate : active;\n                    const Stage recoveryStage = g.stage;\n                    const bool needsApply = confirmed != active;\n                    g.rebootPending = false;\n                    g_bootPrompt = false;\n                    g_bootRecoveryCandidate = -1;\n                    clearVminSweepData();\n\n                    u32 recoveryMask = Config_None;\n                    if (recoveryStage == Stage::LowUvQuick) {\n                        g.lowUvGood = std::max(0, confirmed);\n                        g.lowUvTest = g.lowUvGood;\n                        g.stage = Stage::LowUvLong;\n                        recoveryMask = Config_LowUv;\n                    } else if (recoveryStage == Stage::LowVminQuick) {\n                        g.lowVminGood = confirmed;\n                        g.lowVminTest = g.lowVminGood;\n                        g.stage = Stage::LowVminLong;\n                        recoveryMask = Config_LowVmin;\n                    }\n\n                    if (!needsApply) {\n                        g.pendingConfigMask = Config_None;\n                        g.stageReadyAfterBoot = true;\n                        saveState();\n                    } else {\n                        g.stageReadyAfterBoot = false;\n                        g.pendingConfigMask = recoveryMask;\n                        saveState();\n                        g_autoSetMask = recoveryMask;\n                        g_autoPrepError.clear();\n                        if (applyAutomaticCurrentSetting(recoveryMask)) {\n                            g_configCheck.mask = recoveryMask;\n                            g_rebootConfirm = true;\n                        } else {\n                            g_autoPrepConfirm = true;\n                        }\n                    }\n                }\n                redraw = true;\n            } else if ((k & HidNpadButton_X) && state == BootInference::SaferActive) {\n                if (g_bootRecoveryCandidate < 0) g_bootRecoveryCandidate = active;\n                if (g.stage == Stage::LowUvQuick)\n                    g_bootRecoveryCandidate = std::max(0, g_bootRecoveryCandidate - 1);\n                else if (g.stage == Stage::LowVminQuick)\n                    g_bootRecoveryCandidate = std::min(750, g_bootRecoveryCandidate + LOW_VMIN_STEP_MV);\n                redraw = true;\n            } else if (k & HidNpadButton_X) {\n                g_bootRecoveryCandidate = -1;\n                g.rebootPending = false;\n                g_bootPrompt = false;\n                handleFail(true);\n                redraw = true;\n            } else if (k & HidNpadButton_B) {\n                break;\n            }\n            svcSleepThread(20'000'000);\n            continue;\n        }\n'''
rep(old_boot, new_boot, 'boot prompt input block')

# Known PASS on the scan-complete test page skips the automatic stability test.
rep('''        if (g_vminScanScreen) {\n            if (k & HidNpadButton_A) {\n                if (g_vminScanSuccess) {\n                    g_vminScanScreen = false;\n                    runAutomaticRegionValidation(g_scanForLowUv);\n                    redraw = true;\n                } else {\n                    g_vminScanScreen = false;\n                    if (g_scanForLowUv) runAutomaticLowUvScan();\n                    else runAutomaticVminScan();\n                    redraw = true;\n                }\n            } else if (k & HidNpadButton_B) {''', '''        if (g_vminScanScreen) {\n            if (k & HidNpadButton_A) {\n                if (g_vminScanSuccess) {\n                    g_vminScanScreen = false;\n                    runAutomaticRegionValidation(g_scanForLowUv);\n                    redraw = true;\n                } else {\n                    g_vminScanScreen = false;\n                    if (g_scanForLowUv) runAutomaticLowUvScan();\n                    else runAutomaticVminScan();\n                    redraw = true;\n                }\n            } else if ((k & HidNpadButton_Plus) && g_vminScanSuccess) {\n                g_vminScanScreen = false;\n                skipAutomaticRegionValidation(g_scanForLowUv);\n                redraw = true;\n            } else if (k & HidNpadButton_B) {''', 'scan-screen plus handling')

# Same Known PASS behavior when a persisted state lands directly on the region-test page.
rep('''        } else if ((k & HidNpadButton_Plus) && g.stage != Stage::Preparation) {\n            if (isVminSweepStage(g.stage)) {\n                runAutomaticVminScan();\n            } else {''', '''        } else if ((k & HidNpadButton_Plus) && g.stage != Stage::Preparation) {\n            if (g.stage == Stage::LowUvValidateQuick) {\n                skipAutomaticRegionValidation(true);\n            } else if (g.stage == Stage::LowVminPlateauValidate) {\n                skipAutomaticRegionValidation(false);\n            } else if (isVminSweepStage(g.stage)) {\n                runAutomaticVminScan();\n            } else {''', 'main plus region handling')

p.write_text(s)
print('beta36 patch applied')
